package ru.mirea.orbita;
import android.content.*;
import android.app.*;
import org.json.*;

/** A single persisted alarm queue; inexact idle-aware alarms need no exact-alarm privilege. */
public class LessonReminder extends BroadcastReceiver {
 private static final String PREF="lesson-reminders",CHANNEL="lesson-start";
 public static boolean allowed(Context c){NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);return n.areNotificationsEnabled()&&(android.os.Build.VERSION.SDK_INT<33||c.checkSelfPermission("android.permission.POST_NOTIFICATIONS")==android.content.pm.PackageManager.PERMISSION_GRANTED);}
 private static PendingIntent alarmIntent(Context c){return PendingIntent.getBroadcast(c,881,new Intent(c,LessonReminder.class).setAction("ru.mirea.orbita.LESSON"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 public static synchronized void save(Context c,String payload){try{JSONObject data=new JSONObject(payload);JSONArray clean=new JSONArray(),rows=data.optJSONArray("rows");long now=System.currentTimeMillis();if(data.optBoolean("enabled")&&rows!=null)for(int i=0;i<rows.length()&&clean.length()<500;i++){JSONObject r=rows.optJSONObject(i);if(r==null)continue;long at=r.optLong("at"),start=r.optLong("start");if(at>now&&at<now+40L*86400000&&start>=at&&start<now+42L*86400000&&r.optString("title").length()<1000)clean.put(r);}c.getSharedPreferences(PREF,0).edit().putString("queue",clean.toString()).apply();schedule(c);}catch(Exception ignored){}}
 public static synchronized void schedule(Context c){AlarmManager manager=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);manager.cancel(alarmIntent(c));try{JSONArray rows=new JSONArray(c.getSharedPreferences(PREF,0).getString("queue","[]"));long soon=Long.MAX_VALUE,now=System.currentTimeMillis();for(int i=0;i<rows.length();i++){long at=rows.getJSONObject(i).optLong("at");if(at>now&&at<soon)soon=at;}if(soon!=Long.MAX_VALUE)manager.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,soon,alarmIntent(c));}catch(Exception ignored){}}
 @Override public void onReceive(Context c,Intent intent){if(!"ru.mirea.orbita.LESSON".equals(intent.getAction())){schedule(c);return;}try{JSONArray rows=new JSONArray(c.getSharedPreferences(PREF,0).getString("queue","[]")),future=new JSONArray();long now=System.currentTimeMillis();NotificationManager manager=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);NotificationChannel channel=new NotificationChannel(CHANNEL,"Перед парой",NotificationManager.IMPORTANCE_DEFAULT);channel.setDescription("Напоминания о загруженных занятиях своей группы");manager.createNotificationChannel(channel);for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);long at=row.optLong("at"),start=row.optLong("start");if(at>now+1500){future.put(row);continue;}if(start<=now||!allowed(c))continue;Intent open=new Intent(c,MainActivity.class).putExtra("page","pairs").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);int id=(row.optString("title")+start).hashCode();PendingIntent click=PendingIntent.getActivity(c,id,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);java.text.SimpleDateFormat format=new java.text.SimpleDateFormat("dd.MM HH:mm",java.util.Locale.forLanguageTag("ru"));format.setTimeZone(java.util.TimeZone.getTimeZone("Europe/Moscow"));String body=format.format(new java.util.Date(start))+" · "+row.optString("room")+" · "+row.optString("campus");Notification notification=new Notification.Builder(c,CHANNEL).setSmallIcon(R.drawable.ic_launcher).setContentTitle(row.optString("title")).setContentText(body).setStyle(new Notification.BigTextStyle().bigText(body)).setContentIntent(click).setAutoCancel(true).setShowWhen(true).setWhen(start).build();manager.notify(id,notification);}c.getSharedPreferences(PREF,0).edit().putString("queue",future.toString()).apply();schedule(c);}catch(Exception ignored){}}
}
